<?php

declare(strict_types=1);

use EventMenu\Core\Auth;
use EventMenu\Core\Database;
use EventMenu\Core\Security;
use EventMenu\Services\CashService;
use EventMenu\Services\PaymentService;

Auth::requirePermission('orders.create');$tenantId=em_require_tenant();$cartKey='pos_cart_'.$tenantId;if(!isset($_SESSION[$cartKey])||!is_array($_SESSION[$cartKey]))$_SESSION[$cartKey]=[];$cart=&$_SESSION[$cartKey];
$cashService=Auth::can('cash.manage')?new CashService():null;$cashSession=$cashService?->currentSession();

if($_SERVER['REQUEST_METHOD']==='POST'){
    em_post_csrf();$action=(string)($_POST['action']??'');
    if($action==='add'){
        $id=(int)($_POST['product_id']??0);$qty=max(1,min(99,(int)($_POST['qty']??1)));$s=$pdo->prepare('SELECT id,name,price_cents,track_stock,stock_qty FROM products WHERE id=? AND tenant_id=? AND active=1');$s->execute([$id,$tenantId]);$p=$s->fetch();if(!$p)exit('Produto inválido.');if((int)$p['track_stock']&&(float)$p['stock_qty']<=0)exit('Produto sem estoque.');$cart[$id]=($cart[$id]??0)+$qty;em_go('pos');
    }
    if($action==='remove'){unset($cart[(int)($_POST['product_id']??0)]);em_go('pos');}
    if($action==='clear'){$cart=[];em_go('pos');}
    if($action==='create'){
        if(!$cart)exit('Adicione itens ao pedido.');$channel=(string)($_POST['channel']??'counter');if(!in_array($channel,['counter','pickup','table','delivery'],true))exit('Canal inválido.');$tableId=(int)($_POST['table_id']??0);$name=trim((string)($_POST['customer_name']??''));$phone=trim((string)($_POST['customer_phone']??''));$address=trim((string)($_POST['delivery_address']??''));$notes=mb_substr(trim((string)($_POST['notes']??'')),0,1000);$settle=(string)($_POST['settle']??'later');if(!in_array($settle,['later','cash'],true))exit('Forma de recebimento inválida.');
        if($channel==='delivery'&&($name===''||$phone===''||$address===''))exit('Delivery exige nome, telefone e endereço.');
        if($settle==='cash'&&(!Auth::can('payments.manage')||!Auth::can('cash.manage')))exit('Seu perfil não pode receber pagamentos.');
        try{$result=Database::transaction(function(PDO $tx)use($tenantId,$cart,$channel,$tableId,$name,$phone,$address,$notes,$settle):array{
            $tabId=null;$validTableId=null;if($channel==='table'){$t=$tx->prepare(Database::portableSql($tx,'SELECT id,status FROM restaurant_tables WHERE id=? AND tenant_id=? FOR UPDATE'));$t->execute([$tableId,$tenantId]);$table=$t->fetch();if(!$table||$table['status']==='inactive')throw new RuntimeException('Mesa inválida.');$tab=$tx->prepare(Database::portableSql($tx,'SELECT id FROM tabs WHERE tenant_id=? AND table_id=? AND status="open" ORDER BY id DESC LIMIT 1 FOR UPDATE'));$tab->execute([$tenantId,$tableId]);$tabId=$tab->fetchColumn();if($tabId===false)throw new RuntimeException('Abra uma comanda para esta mesa antes de lançar o pedido.');$validTableId=$tableId;}
            $customerId=null;if($name!==''){$existing=null;if($phone!==''){$c=$tx->prepare('SELECT id FROM customers WHERE tenant_id=? AND phone=? ORDER BY id DESC LIMIT 1');$c->execute([$tenantId,$phone]);$existing=$c->fetchColumn();}if($existing!==false&&$existing!==null)$customerId=(int)$existing;else{$c=$tx->prepare('INSERT INTO customers (tenant_id,name,phone) VALUES (?,?,?)');$c->execute([$tenantId,$name,$phone?:null]);$customerId=(int)$tx->lastInsertId();}}
            $items=[];$total=0;foreach($cart as $productId=>$qty){$qty=max(1,(int)$qty);$p=$tx->prepare('SELECT id,name,price_cents,track_stock,stock_qty FROM products WHERE id=? AND tenant_id=? AND active=1');$p->execute([(int)$productId,$tenantId]);$product=$p->fetch();if(!$product)throw new RuntimeException('Um produto do carrinho não está mais disponível.');if((int)$product['track_stock']&&(float)$product['stock_qty']<$qty)throw new RuntimeException('Estoque insuficiente para '.$product['name'].'.');$line=(int)$product['price_cents']*$qty;$total+=$line;$items[]=['id'=>(int)$product['id'],'name'=>$product['name'],'price'=>(int)$product['price_cents'],'qty'=>$qty,'total'=>$line];}
            if($total<=0)throw new RuntimeException('Pedido sem valor válido.');$token=bin2hex(random_bytes(20));$o=$tx->prepare('INSERT INTO orders (public_token,tenant_id,customer_id,channel,status,payment_status,subtotal_cents,total_cents,table_id,tab_id,delivery_address,notes,created_by) VALUES (?,?,?,?,"confirmed","unpaid",?,?,?,?,?,?,?)');$o->execute([$token,$tenantId,$customerId,$channel,$total,$total,$validTableId,$tabId,$channel==='delivery'?$address:null,$notes?:null,Auth::id()]);$orderId=(int)$tx->lastInsertId();$i=$tx->prepare('INSERT INTO order_items (order_id,product_id,name_snapshot,unit_price_cents,quantity,total_cents) VALUES (?,?,?,?,?,?)');foreach($items as $item)$i->execute([$orderId,$item['id'],$item['name'],$item['price'],$item['qty'],$item['total']]);Auth::audit('order.created_pos','order',(string)$orderId,['channel'=>$channel,'total_cents'=>$total]);
            if($settle==='cash'){$cash=new CashService();if(!$cash->currentSession())throw new RuntimeException('Abra seu turno de caixa antes de receber dinheiro.');$payments=new PaymentService();$payment=$payments->create($orderId,'manual','pos-cash:'.$tenantId.':'.$orderId.':'.bin2hex(random_bytes(8)));$payments->confirmVerified(['tenant_id'=>$tenantId,'order_id'=>$orderId,'provider'=>'manual','provider_payment_id'=>'CASH-POS-'.strtoupper(bin2hex(random_bytes(8))),'amount_cents'=>$total,'currency'=>'BRL','account_reference'=>'manual']);$cash->recordPaidPayment((int)$payment['id'],'cash');Auth::audit('payment.cash_pos','order',(string)$orderId);}
            return ['order_id'=>$orderId,'paid'=>$settle==='cash'];});$cart=[];$orderId=(int)$result['order_id'];em_flash('ok',$result['paid']?'Pedido #'.$orderId.' criado e recebido em dinheiro.':'Pedido #'.$orderId.' criado no PDV.');em_go('orders',['view'=>$orderId]);}catch(Throwable $e){em_flash('error',$e->getMessage());em_go('pos');}
    }
}

$p=$pdo->prepare('SELECT p.*,c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.tenant_id=? AND p.active=1 ORDER BY c.sort_order,c.name,p.name');$p->execute([$tenantId]);$products=$p->fetchAll();$tables=$pdo->prepare('SELECT rt.id,rt.name,t.id tab_id,t.label FROM restaurant_tables rt JOIN tabs t ON t.table_id=rt.id AND t.status="open" WHERE rt.tenant_id=? AND rt.status<>"inactive" ORDER BY rt.name');$tables->execute([$tenantId]);$tables=$tables->fetchAll();
$cartRows=[];$cartTotal=0;foreach($cart as $id=>$qty){foreach($products as $p){if((int)$p['id']!==(int)$id)continue;$line=(int)$p['price_cents']*(int)$qty;$cartTotal+=$line;$cartRows[]=['id'=>(int)$id,'name'=>$p['name'],'qty'=>(int)$qty,'line'=>$line];break;}}
em_header('Caixa / PDV','pos');
?><?php if(Auth::can('cash.manage')&&!$cashSession):?><div class="alert error">Seu turno de caixa está fechado. Você pode criar pedidos para pagar depois, mas para receber dinheiro precisa <a href="<?= Security::e(app_url('?route=cash')) ?>">abrir o caixa</a>.</div><?php endif;?><div class="grid" style="grid-template-columns:minmax(0,2fr) minmax(300px,1fr)"><section><div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(220px,1fr))"><?php foreach($products as $p):?><article class="card"><span class="muted"><?= Security::e($p['category_name']??'Sem categoria') ?></span><h3><?= Security::e($p['name']) ?></h3><p><strong><?= em_money($p['price_cents']) ?></strong><?php if($p['track_stock']):?><br><span class="muted">Estoque: <?= Security::e((string)$p['stock_qty']) ?></span><?php endif;?></p><form method="post" class="actions"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="add"><input type="hidden" name="product_id" value="<?= (int)$p['id'] ?>"><input type="number" name="qty" min="1" max="99" value="1" style="width:72px"><button class="primary">Adicionar</button></form></article><?php endforeach;?></div></section><aside class="card"><div class="section-head"><h2>Pedido</h2><?php if($cart):?><form method="post"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="clear"><button class="secondary">Limpar</button></form><?php endif;?></div><?php if(!$cartRows):?><p class="muted">Carrinho vazio.</p><?php else:?><?php foreach($cartRows as $i):?><div class="section-head"><span><?= $i['qty'] ?>× <?= Security::e($i['name']) ?><br><strong><?= em_money($i['line']) ?></strong></span><form method="post"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="remove"><input type="hidden" name="product_id" value="<?= $i['id'] ?>"><button class="secondary">×</button></form></div><?php endforeach;?><hr style="border-color:var(--line)"><h2>Total <?= em_money($cartTotal) ?></h2><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="create"><label class="span-2">Origem<select name="channel" id="pos-channel"><option value="counter">Balcão</option><option value="pickup">Retirada</option><option value="table">Mesa</option><option value="delivery">Delivery</option></select></label><label class="span-2">Recebimento<select name="settle"><option value="later">Pagar depois</option><?php if(Auth::can('payments.manage')&&Auth::can('cash.manage')):?><option value="cash"<?= !$cashSession?' disabled':'' ?>>Dinheiro<?= !$cashSession?' — abra o caixa':'' ?></option><?php endif;?></select></label><label class="span-2">Mesa / comanda<select name="table_id"><option value="0">Selecione quando for mesa</option><?php foreach($tables as $t):?><option value="<?= (int)$t['id'] ?>"><?= Security::e($t['name'].' · Comanda #'.$t['tab_id'].($t['label']?' · '.$t['label']:'')) ?></option><?php endforeach;?></select></label><label class="span-2">Cliente<input name="customer_name" placeholder="Opcional, exceto delivery"></label><label class="span-2">Telefone<input name="customer_phone"></label><label class="span-2">Endereço delivery<textarea name="delivery_address"></textarea></label><label class="span-2">Observações<textarea name="notes"></textarea></label><button class="primary span-2">Finalizar pedido</button></form><?php endif;?></aside></div><?php em_footer();